return {["Sheet1"]={["mianju1000"]={["id"]=[[mianju1000]],["name"]=[[嫦娥]],["text"]=[[YEL莫啸:月宫仙子临凡，真是咱们这的福气，请进。]],["text1"]=[[我也好想去月宫看看啊。;北方有佳人，遗世而独立..]]},["mianju1001"]={["id"]=[[mianju1001]],["name"]=[[吴刚]],["text"]=[[YEL莫啸:您今天不用砍树了？请进请进。]],["text1"]=[[月桂树是会不断生长的吗？你为什么能一直砍？;嫦娥长得好看不？]]},["mianju1002"]={["id"]=[[mianju1002]],["name"]=[[童姥]],["text"]=[[YEL莫啸:天山的贵客，请进。]],["text1"]=[[我要是也能像你这么童颜永驻就好了。;你可有什么特殊的保养之法？]]},["mianju1003"]={["id"]=[[mianju1003]],["name"]=[[王维]],["text"]=[[YEL莫啸:王右丞也爱热闹啊，请进。]],["text1"]=[[您就是“诗中有画，画中有诗”那位？;阁下不是喜欢清静，怎么也上这来了。]]},["mianju1004"]={["id"]=[[mianju1004]],["name"]=[[郭少侠]],["text"]=[[YEL莫啸:郭少侠，稀客稀客！快快请进。]],["text1"]=[[神功盖世，美人在卧，真是好福气。;中秋佳节，你怎会一个人在外闲逛？]]},["mianju1005"]={["id"]=[[mianju1005]],["name"]=[[杨公子]],["text"]=[[YEL莫啸:全真高徒杨公子能莅临此处，真是不盛荣幸。]],["text1"]=[[哼，卖国贼。;杨公子今天上哪快活啊？]]},["mianju1006"]={["id"]=[[mianju1006]],["name"]=[[穆女侠]],["text"]=[[YEL莫啸:穆女侠可真是赶巧了，咱们这正在比武，您可得看看。]],["text1"]=[[你不就是那个比武招亲的谁来着？;真是女中豪杰啊。]]},["mianju1007"]={["id"]=[[mianju1007]],["name"]=[[程姑娘]],["text"]=[[YEL莫啸:程姑娘怎么有空上这来？请进请进。]],["text1"]=[[姑娘真是妙手神医啊。;我家中有人怪病缠身，姑娘要是何日能去看看就好了。]]},["mianju1008"]={["id"]=[[mianju1008]],["name"]=[[郭小姐]],["text"]=[[YEL莫啸:这不是郭大侠的千金郭小姐吗！快快请进。]],["text1"]=[[你是…郭家小女儿？;听说你有个顽劣的姐姐，真是辛苦啊。]]},["mianju1009"]={["id"]=[[mianju1009]],["name"]=[[苗姑娘]],["text"]=[[YEL莫啸:苗姑娘，今日怎么没和令尊一起来啊？]],["text1"]=[[姑娘也有兴致来赶这庙会啊。;我曾受苗大侠照顾，只可惜好人不长命。]]},["mianju1010"]={["id"]=[[mianju1010]],["name"]=[[令狐少侠]],["text"]=[[YEL莫啸:阁下可是华山大弟子令狐少侠？真是稀客。]],["text1"]=[[改日一起喝酒啊。;我知道你，屁股向后平沙落雁式！]]},["mianju1011"]={["id"]=[[mianju1011]],["name"]=[[岳小妹]],["text"]=[[YEL莫啸:华山的高徒，请进。]],["text1"]=[[姑娘可真是俏皮可爱。;你大师兄今年又要送你什么好玩意吧。]]},["mianju1012"]={["id"]=[[mianju1012]],["name"]=[[杨大侠]],["text"]=[[YEL莫啸:销声匿迹的杨大侠没想到今日能上这来，真是荣幸之至。]],["text1"]=[[你的雕呢？;咦？杨大侠不是独臂么，你是什么人？]]},["mianju1013"]={["id"]=[[mianju1013]],["name"]=[[龙姑娘]],["text"]=[[YEL莫啸:能得到不食人间烟火的龙姑娘光临，真是蓬荜生辉。]],["text1"]=[[仙、仙女…;龙姑娘兴致真好。]]},["mianju1014"]={["id"]=[[mianju1014]],["name"]=[[李仙姑]],["text"]=[[YEL莫啸:李仙姑今日真是好兴致，快快请进。]],["text1"]=[[仙姑面纱之下究竟是何容貌呢。;姑娘为何不以真容示人呢。]]},["mianju1015"]={["id"]=[[mianju1015]],["name"]=[[向先生]],["text"]=[[YEL莫啸:今日是什么风把向先生吹到这来了。]],["text1"]=[[你就是那个神功盖世的向先生吗？;神教的人也会对庙会感兴趣啊。]]},["mianju1016"]={["id"]=[[mianju1016]],["name"]=[[木姑娘]],["text"]=[[YEL莫啸:您是木姑娘吧，请进。]],["text1"]=[[姑娘怎会孤身一人至此？;我看姑娘也是女中豪杰吧。]]},["mianju1017"]={["id"]=[[mianju1017]],["name"]=[[段公子]],["text"]=[[YEL莫啸:这不是大理国的段公子吗！真是贵客！]],["text1"]=[[嘿，今天又和哪家姑娘出来的？;段公子真是一表人才。]]},["mianju1018"]={["id"]=[[mianju1018]],["name"]=[[慕容公子]],["text"]=[[YEL莫啸:您是龙城山庄的慕容公子吧？请进。]],["text1"]=[[慕容公子真是相貌堂堂。;龙城山庄真富有。]]},["mianju1019"]={["id"]=[[mianju1019]],["name"]=[[丁老仙]],["text"]=[[YEL莫啸:您是丁老仙？快快请进。]],["text1"]=[[你就是那个什么“星宿老仙，法力无边”？;听说你毒功十分了得。]]},["mianju1020"]={["id"]=[[mianju1020]],["name"]=[[岳先生]],["text"]=[[YEL莫啸:您是华山的岳先生吗？还请上座。]],["text1"]=[[岳先生真是一派君子风范。;君子剑岳先生，早闻大名。]]},["mianju1021"]={["id"]=[[mianju1021]],["name"]=[[黑无常]],["text"]=[[YEL莫啸:扮作黑无常来逛庙会，阁下还真是奇特。请进吧。]],["text1"]=[[鬼啊！;别、别抓我！]]},["mianju1022"]={["id"]=[[mianju1022]],["name"]=[[白无常]],["text"]=[[YEL莫啸:白无常？阁下倒是扮得挺像。请进。]],["text1"]=[[大爷饶命！;我还不想死！]]},["mianju1023"]={["id"]=[[mianju1023]],["name"]=[[梅大侠]],["text"]=[[YEL莫啸:梅大侠也爱看热闹啊。请进。]],["text1"]=[[你就是那个梅大侠啊。;你看起来好面熟，但我一时想不起来。]]},["mianju1024"]={["id"]=[[mianju1024]],["name"]=[[神雕]],["text"]=[[YEL莫啸:好大的雕！让你进去可以，可别闹事啊。]],["text1"]=[[你听得懂人话吗？;叽叽叽…唉不对，雕语怎么说？]]},["mianju1025"]={["id"]=[[mianju1025]],["name"]=[[岳老三]],["text"]=[[YEL莫啸:岳老三…你可别惹是生非啊。]],["text1"]=[[我不想与恶人说话。;岳老三？走开走开。]]},["mianju1026"]={["id"]=[[mianju1026]],["name"]=[[屈原]],["text"]=[[YEL莫啸:屈先生也来这看热闹？请进请进！]],["text1"]=[[你不是早就投江了吗…;先生高风亮节，后生晚辈佩服。]]},["mianju1027"]={["id"]=[[mianju1027]],["name"]=[[湘夫人]],["text"]=[[YEL莫啸:湘夫人难得有此好兴致，请进。]],["text1"]=[[夫人真是洛神之姿。;我好像在湘夫人庙见过你？]]},["mianju1028"]={["id"]=[[mianju1028]],["name"]=[[黄姑娘]],["text"]=[[YEL莫啸:咦？黄姑娘？这不可能啊。]],["text1"]=[[咦？黄姑娘？这不可能啊。]]},["mianju1029"]={["id"]=[[mianju1029]],["name"]=[[任大小姐]],["text"]=[[YEL莫啸:咦？任大小姐？这不可能啊。]],["text1"]=[[咦？任大小姐？这不可能啊。]]},["mianju1030"]={["id"]=[[mianju1030]],["name"]=[[钟姑娘]],["text"]=[[YEL莫啸:咦？钟姑娘？这不可能啊。]],["text1"]=[[咦？钟姑娘？这不可能啊。]]},["mianju1031"]={["id"]=[[mianju1031]],["name"]=[[青小婉]],["text"]=[[YEL莫啸:小婉姑娘也来啦？请进请进。]],["text1"]=[[你就是小婉姑娘吗？;姑娘看起来像我幼时的青梅竹马。]]},["mianju1032"]={["id"]=[[mianju1032]],["name"]=[[柳玄风]],["text"]=[[YEL莫啸:柳玄风…今日只谈中秋庙会，别的都不提。]],["text1"]=[[没想到今天能一睹柳玄风真容。;你好像是那个被各大门派通缉的人？]]},["mianju1033"]={["id"]=[[mianju1033]],["name"]=[[洛还君]],["text"]=[[YEL莫啸:姑娘是落月山庄的洛还君吧？稀客稀客。]],["text1"]=[[姑娘也是武林中人？有些眼生。;这不是洛姑娘吗，我以前曾去过落月山庄嘞。]]},["mianju1034"]={["id"]=[[mianju1034]],["name"]=[[牛郎]],["text"]=[[YEL莫啸:人可以进去，牛可不能带进去啊。]],["text1"]=[[我好像在画卷上见过你。;牛郎吗？一个人逛庙会，真可怜。]]},["mianju1035"]={["id"]=[[mianju1035]],["name"]=[[织女]],["text"]=[[YEL莫啸:姑娘可真是美若天仙，请进吧。]],["text1"]=[[姑娘看起来风姿出尘，不像凡人。;天上的云都是你织的吗？]]},["mianju1036"]={["id"]=[[mianju1036]],["name"]=[[落水鬼]],["text"]=[[YEL莫啸:擦干水再进去，免得招惹别的游人。]],["text1"]=[[鬼啊！;别过来！]]},["mianju1037"]={["id"]=[[mianju1037]],["name"]=[[无面鬼]],["text"]=[[YEL莫啸:我是吓不到的，你可别吓到别的游人。]],["text1"]=[[没脸的妖怪！;救命啊！]]},["mianju1038"]={["id"]=[[mianju1038]],["name"]=[[长发鬼]],["text"]=[[YEL莫啸:我看你气色不太好，进去找个茶水摊喝杯热茶吧。]],["text1"]=[[你怎么会没有影子..;长发妖怪！]]},["mianju1039"]={["id"]=[[mianju1039]],["name"]=[[大头鬼]],["text"]=[[YEL莫啸:把你的三眼遮起来再进去吧。]],["text1"]=[[三眼的恶鬼！;别吃我，我还不想死！]]},["mianju1040"]={["id"]=[[mianju1040]],["name"]=[[鬼王]],["text"]=[[YEL莫啸:你这扮相怎会如此骇人？可别吓坏了别的游人。]],["text1"]=[[我没做过坏事，大爷放我一马！;光天化日见鬼了！]]},["mianju1041"]={["id"]=[[mianju1041]],["name"]=[[后羿]],["text"]=[[YEL莫啸:哪有人拿着弓箭逛庙会的？别伤着游人。]],["text1"]=[[你是传说中的那个射日的？;阁下的弓好帅呀！]]},["mianju1042"]={["id"]=[[mianju1042]],["name"]=[[月兔]],["text"]=[[YEL莫啸:逛庙会的兔子我倒是头一次见。]],["text1"]=[[哪里跑来的兔子？;逛庙会的兔子？？]]},["xinwu200_01"]={["id"]=[[xinwu200_01]],["name"]=[[北落师门]],["text"]=[[YEL莫啸:哟，这不是盛唐阁的二当家吗，快请进，快请进。]],["text1"]=[[您老平日神龙见首不见尾，可是难得见一面啊。;你们盛唐阁还要人吗？一直想拜入盛唐阁就是找不到门路。]]},["xinwu200_02"]={["id"]=[[xinwu200_02]],["name"]=[[十八]],["text"]=[[YEL莫啸:十八爷老些日子不见了，请进请进。]],["text1"]=[[十八爷待会一起喝酒去，这次我请客。;上次有幸看到十八爷的纯金算盘，真可谓是开了眼了。]]},["xinwu200_03"]={["id"]=[[xinwu200_03]],["name"]=[[何虚名]],["text"]=[[YEL莫啸:这不是虚名道长吗，难得神游到此，请进请进。]],["text1"]=[[虚名兄你的棋子是什么做的？为什么好像有点点星辰。;知道虚名兄曲高和寡，但听君一曲真是三日不觉肉味。]]},["xinwu200_04"]={["id"]=[[xinwu200_04]],["name"]=[[王真一]],["text"]=[[YEL莫啸:哈哈，真一道长，您今年又来啦，上次咱们扬州的姑娘还对您念念不忘嘞。]],["text1"]=[[真一道长，听说你的剑法乃是武林一绝，能不能让我也看看呐？;真一道长，您这宝剑镶金嵌玉的，怕是花了不少钱打造吧。]]},["xinwu200_05"]={["id"]=[[xinwu200_05]],["name"]=[[天蚕]],["text"]=[[YEL莫啸:看这只铁笔准是天蚕，请进请进。]],["text1"]=[[天蚕你这个名字是什么意思啊。;看这手八步判官没猜错的话，应该是天蚕吧。]]},["xinwu200_06"]={["id"]=[[xinwu200_06]],["name"]=[[柳如烟]],["text"]=[[YEL莫啸:盛唐阁名满天下的柳如烟姑娘，能来我们这小小的庙会，我真是感到荣幸呐，快请进。]],["text1"]=[[你是那个柳姑娘！能给我签个名么？;如烟姑娘，我..我也是你的追随者…]]},["xinwu200_07"]={["id"]=[[xinwu200_07]],["name"]=[[剑客]],["text"]=[[YEL莫啸:拿着断刃残剑闯荡江湖的侠客就只有盛唐阁的剑客，能来我们这那可真是蓬荜生辉。]],["text1"]=[[你的剑是怎么断的？;上次见你的时候还有个俊俏女子，今天怎么没有看到。]]},["xinwu200_08"]={["id"]=[[xinwu200_08]],["name"]=[[肖老]],["text"]=[[YEL莫啸:这次庙会有一半是肖老你帮着建的，若小的把你拦住不让进，那小的也太不是东西了。]],["text1"]=[[肖老能不能收我为徒。;肖老有些日子不见，改天一定来我家坐坐。]]},["xinwu200_09"]={["id"]=[[xinwu200_09]],["name"]=[[唐长老]],["text"]=[[YEL莫啸:唐长老今天得空能来这小小的庙会，小的实在是高兴。]],["text1"]=[[长老待会到我家坐坐，最近得了点小玩意，还望长老你掌掌眼。;唐长老上次你给修的东西又出了毛病，待会能不能再给修一下。]]},["xinwu200_10"]={["id"]=[[xinwu200_10]],["name"]=[[雨珊]],["text"]=[[YEL莫啸:盛唐阁的雨珊姑娘，今日可有雅兴。]],["text1"]=[[盛唐阁是个什么地方？;你是…想不起来了。]]},["xinwu200_11"]={["id"]=[[xinwu200_11]],["name"]=[[如来]],["text"]=[[YEL莫啸:你是...啊..难道是盛唐阁大当家，小的给你老请安，请进请进。]],["text1"]=[[平日只闻其名未见其人，今天总算是见到真人了。;“如来”之名可谓是如雷贯耳，今日得见，真可谓三生有幸。]]},["xinwu200_12"]={["id"]=[[xinwu200_12]],["name"]=[[秋珊灵]],["text"]=[[YEL莫啸:您是盛唐阁的秋姑娘吧？请进请进。]],["text1"]=[[秋姑娘，何日与我把酒言欢啊。;姑娘真是温婉动人。]]}},["Sheet2"]={},["Sheet3"]={}}0000000000000